import{_ as i,o as t,c as a,an as n}from"./chunks/framework.Ctf_xftG.js";const p=JSON.parse('{"title":"4 - Offensive .NET","description":"","frontmatter":{"title":"4 - Offensive .NET"},"headers":[],"relativePath":"crtp/offensive-dotnet.md","filePath":"crtp/offensive-dotnet.md"}'),s={name:"crtp/offensive-dotnet.md"};function r(o,e,d,l,c,u){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="offensive-net" tabindex="-1">Offensive .NET <a class="header-anchor" href="#offensive-net" aria-label="Permalink to &quot;Offensive .NET&quot;">​</a></h1><h2 id="outils-net" tabindex="-1">Outils .NET <a class="header-anchor" href="#outils-net" aria-label="Permalink to &quot;Outils .NET&quot;">​</a></h2><p>Les outils développés en C# peuvent interagir avec Windows, Active Directory et les mécanismes d&#39;authentification. Leur exécution peut prendre la forme d&#39;un binaire .NET ou d&#39;un chargement en mémoire.</p><h2 id="detection-antivirus" tabindex="-1">Détection antivirus <a class="header-anchor" href="#detection-antivirus" aria-label="Permalink to &quot;Détection antivirus&quot;">​</a></h2><p>Les notes d&#39;origine présentent plusieurs méthodes qui modifient la forme d&#39;un binaire : obfuscation, modification de chaînes, compression et intégration de contenu dans un programme.</p><p>Ces modifications peuvent changer les indicateurs statiques d&#39;un fichier. Elles ne changent pas nécessairement son comportement à l&#39;exécution.</p><h3 id="defendercheck" tabindex="-1">DefenderCheck <a class="header-anchor" href="#defendercheck" aria-label="Permalink to &quot;DefenderCheck&quot;">​</a></h3><p>DefenderCheck sert à identifier les parties d&#39;un binaire susceptibles de déclencher une détection Windows Defender. Dans un audit défensif, ces résultats aident à comprendre les éléments signalés par l&#39;antivirus.</p><h3 id="sharpkatz" tabindex="-1">SharpKatz <a class="header-anchor" href="#sharpkatz" aria-label="Permalink to &quot;SharpKatz&quot;">​</a></h3><p>SharpKatz est un outil .NET qui reprend certaines fonctionnalités de Mimikatz. Les usages présentés dans les notes concernent des données d&#39;authentification Windows.</p><h3 id="safetykatz" tabindex="-1">SafetyKatz <a class="header-anchor" href="#safetykatz" aria-label="Permalink to &quot;SafetyKatz&quot;">​</a></h3><p>SafetyKatz associe des fonctionnalités de Mimikatz à un mécanisme de chargement en mémoire. Les notes d&#39;origine décrivent également l&#39;utilisation d&#39;un contenu compressé.</p><h3 id="bettersafetykatz" tabindex="-1">BetterSafetyKatz <a class="header-anchor" href="#bettersafetykatz" aria-label="Permalink to &quot;BetterSafetyKatz&quot;">​</a></h3><p>Les notes présentent une variante qui intègre le contenu d&#39;une archive directement dans le programme. Cette méthode modifie le mode de stockage et de chargement du binaire.</p><h3 id="rubeus" tabindex="-1">Rubeus <a class="header-anchor" href="#rubeus" aria-label="Permalink to &quot;Rubeus&quot;">​</a></h3><p>Rubeus est un outil orienté Kerberos. Les notes d&#39;origine mentionnent l&#39;obfuscation de son binaire et la modification de métadonnées d&#39;assembly.</p><h2 id="payload-delivery" tabindex="-1">Payload Delivery <a class="header-anchor" href="#payload-delivery" aria-label="Permalink to &quot;Payload Delivery&quot;">​</a></h2><p>Les notes présentent NetLoader et AssemblyLoad comme des outils de chargement de binaires depuis un chemin local ou une URL.</p><p>NetLoader est également associé à des modifications d&#39;AMSI et d&#39;ETW. Ces mécanismes sont sensibles, car ils peuvent réduire la visibilité des outils de sécurité sur l&#39;exécution PowerShell et .NET.</p><h3 id="indicateurs-a-surveiller" tabindex="-1">Indicateurs à surveiller <a class="header-anchor" href="#indicateurs-a-surveiller" aria-label="Permalink to &quot;Indicateurs à surveiller&quot;">​</a></h3><ul><li>Chargement inattendu d&#39;assemblies .NET en mémoire.</li><li>Exécution de binaires depuis des répertoires inhabituels ou des URL distantes.</li><li>Modifications inattendues des mécanismes AMSI et ETW.</li><li>Connexions réseau initiées par un processus qui n&#39;en a pas habituellement besoin.</li></ul><h2 id="chemins-de-compromission-du-laboratoire" tabindex="-1">Chemins de compromission du laboratoire <a class="header-anchor" href="#chemins-de-compromission-du-laboratoire" aria-label="Permalink to &quot;Chemins de compromission du laboratoire&quot;">​</a></h2><p>Les deux scénarios ci-dessous sont décrits au niveau des mécanismes et des traces à rechercher. Les commandes de contournement, de chargement furtif et d&#39;extraction d&#39;identifiants ne sont pas reproduites.</p><h3 id="scenario-1-dcorp-ci" tabindex="-1">Scénario 1 - dcorp-ci <a class="header-anchor" href="#scenario-1-dcorp-ci" aria-label="Permalink to &quot;Scénario 1 - dcorp-ci&quot;">​</a></h3><p>Le scénario associe l&#39;administration distante via WinRM, le transfert d&#39;un binaire, une redirection de port locale et l&#39;accès à des données d&#39;authentification. Il se termine par l&#39;utilisation de matériel Kerberos associé à un compte privilégié.</p><p><strong>Points de surveillance</strong></p><ul><li>Sessions WinRM inattendues et commandes distantes inhabituelles.</li><li>Copie de binaires vers des partages administratifs.</li><li>Modification de la configuration portproxy.</li><li>Accès anormal au processus LSASS.</li><li>Activité Kerberos inhabituelle liée à des comptes privilégiés.</li></ul><h3 id="scenario-2-droits-administrateur-locaux-indirects" tabindex="-1">Scénario 2 - Droits administrateur locaux indirects <a class="header-anchor" href="#scenario-2-droits-administrateur-locaux-indirects" aria-label="Permalink to &quot;Scénario 2 - Droits administrateur locaux indirects&quot;">​</a></h3><p>Ce scénario part d&#39;un compte disposant de droits administrateur locaux sur une machine. Il examine ensuite les possibilités d&#39;administration distante, les restrictions du langage PowerShell et les règles AppLocker.</p><p>La présence de droits administrateur locaux sur une machine ne donne pas automatiquement des privilèges sur le domaine. Le risque apparaît lorsque ces droits permettent d&#39;accéder à une autre machine ou à une session contenant des données d&#39;authentification sensibles.</p><p><strong>Points de surveillance</strong></p><ul><li>Utilisation inhabituelle de PowerShell Remoting.</li><li>Restrictions Constrained Language et règles AppLocker modifiées ou contournées.</li><li>Copie de scripts ou d&#39;outils d&#39;administration vers des machines distantes.</li><li>Accès à LSASS et utilisation de tickets Kerberos depuis une session inattendue.</li></ul><h2 id="controles-defensifs" tabindex="-1">Contrôles défensifs <a class="header-anchor" href="#controles-defensifs" aria-label="Permalink to &quot;Contrôles défensifs&quot;">​</a></h2><ul><li>Limiter les comptes disposant de droits administrateur locaux.</li><li>Restreindre et journaliser l&#39;administration distante.</li><li>Appliquer les règles AppLocker et contrôler leur modification.</li><li>Surveiller les accès à LSASS et les chargements .NET inhabituels.</li><li>Contrôler les modifications d&#39;AMSI, d&#39;ETW et de la configuration réseau.</li><li>Corréler les événements PowerShell, WinRM, Defender et Kerberos.</li></ul>',34)]))}const h=i(s,[["render",r]]);export{p as __pageData,h as default};
